    const verify = jest.fn();
    const api = jest.fn();

    beforeEach(() => {
        verify.mockReset();
        api.mockReset();
    });

    it('returns a chargeable token without verification', async () => {
        api.mockResolvedValue({ Token, Status: PAYMENT_TOKEN_STATUS.STATUS_CHARGEABLE });
        await expect(createPaymentToken({ params, api, verify })).resolves.toEqual({
            Payment: { Type: PAYMENT_METHOD_TYPES.TOKEN, Details: { Token } },
        });
        expect(verify).not.toHaveBeenCalled();
    });

    it('passes pending tokens to the injected verifier', async () => {
        const result = { Payment: { Type: PAYMENT_METHOD_TYPES.TOKEN, Details: { Token } } };
        api.mockResolvedValue({
            Token,
            Status: PAYMENT_TOKEN_STATUS.STATUS_PENDING,
            ApprovalURL: 'approval',
            ReturnHost: 'return',
        });
        verify.mockResolvedValue(result);
        await expect(getCreatePaymentToken(verify)({ params, api })).resolves.toBe(result);
        expect(verify).toHaveBeenCalledWith({
            mode: undefined,
            Payment: undefined,
            Token,
            ApprovalURL: 'approval',
            ReturnHost: 'return',
        });
    });

    it.each([
        PAYMENT_TOKEN_STATUS.STATUS_FAILED,
        PAYMENT_TOKEN_STATUS.STATUS_CONSUMED,
        PAYMENT_TOKEN_STATUS.STATUS_NOT_SUPPORTED,
    ])('rejects terminal creation status %s', async (Status) => {
        api.mockResolvedValue({ Token, Status });
        await expect(createPaymentToken({ params, api, verify })).rejects.toThrow();
        expect(verify).not.toHaveBeenCalled();
    });
});

